/* FileKit core utilities — shared, XSS-safe helpers.
   Everything hangs off a single global namespace: window.FF */
(() => {
  'use strict';
  const FF = (window.FF = window.FF || {});

  // --- XSS-safe HTML escaping (the ONE canonical implementation) ---
  const ENT = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  const escapeHtml = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ENT[c]);

  // --- byte formatting ---
  const bytes = (n) => {
    n = Number(n) || 0;
    if (n < 1024) return `${n} B`;
    if (n < 1048576) return `${(n / 1024).toFixed(1)} KB`;
    if (n < 1073741824) return `${(n / 1048576).toFixed(1)} MB`;
    return `${(n / 1073741824).toFixed(2)} GB`;
  };

  // --- safe download (filename is NEVER injected into HTML/attributes) ---
  function downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename || 'download';
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // --- object-URL registry so previews never leak memory ---
  const _urls = new Set();
  function objectURL(blob) {
    const u = URL.createObjectURL(blob);
    _urls.add(u);
    return u;
  }
  function revokeAll() {
    for (const u of _urls) URL.revokeObjectURL(u);
    _urls.clear();
  }

  // --- cooperative cancellation helpers ---
  function throwIfAborted(signal) {
    if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
  }
  async function yieldToMain(signal) {
    throwIfAborted(signal);
    await new Promise((resolve) => setTimeout(resolve, 0));
    throwIfAborted(signal);
  }

  // --- strip extension / build output name from a source name safely ---
  const baseName = (name) => String(name || 'file').replace(/\.[^.]+$/, '');
  const extOf = (name) => (String(name || '').split('.').pop() || '').toLowerCase();

  // --- tiny DOM builder that escapes text by default ---
  function el(tag, props = {}, children = []) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(props)) {
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;               // safe text
      else if (k === 'html') node.innerHTML = v;                 // caller guarantees safety
      else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
      else if (k === 'dataset') Object.assign(node.dataset, v);
      else if (v !== false && v != null) node.setAttribute(k, v);
    }
    for (const c of [].concat(children)) if (c != null) node.append(c);
    return node;
  }

  // --- lazy library loader (same-origin, SRI-verified, de-duplicated) ---
  const _loaded = new Map();
  function loadScript(src, integrity) {
    if (_loaded.has(src)) return _loaded.get(src);
    const p = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      if (integrity) s.integrity = integrity;
      s.onload = () => resolve();
      s.onerror = () => { _loaded.delete(src); reject(new Error('Could not load engine: ' + src)); };
      document.head.append(s);
    });
    _loaded.set(src, p);
    return p;
  }
  async function loadScripts(list) { for (const [src, sri] of list) await loadScript(src, sri); }

  async function textToPdf(PDFLib, text, name) {
    const doc = await PDFLib.PDFDocument.create(); const font = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
    const size = 11, margin = 50, lineH = 15, pw = 595, ph = 842, maxW = pw - margin * 2;
    const clean = (s) => String(s).replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF]/g, '?');
    const wrap = (line) => { const words = clean(line).split(' '); const out = []; let cur = ''; for (const w of words) { const t = cur ? cur + ' ' + w : w; if (font.widthOfTextAtSize(t, size) > maxW) { if (cur) out.push(cur); cur = w; } else cur = t; } out.push(cur); return out.length ? out : ['']; };
    const lines = []; for (const raw of clean(text).split(/\r?\n/)) for (const l of wrap(raw)) lines.push(l);
    let page = doc.addPage([pw, ph]), y = ph - margin;
    for (const l of lines) { if (y < margin) { page = doc.addPage([pw, ph]); y = ph - margin; } page.drawText(l, { x: margin, y, size, font, color: PDFLib.rgb(0.1, 0.1, 0.1) }); y -= lineH; }
    return { blob: new Blob([await doc.save()], { type: 'application/pdf' }), filename: name, mime: 'application/pdf', preview: 'download' };
  }

  // --- Toast notification system (accessible, theme-consistent, no blocking native alerts) ---
  let _toastContainer = null;
  function toast(message, type = 'info', duration = 3600) {
    if (!_toastContainer) {
      _toastContainer = document.createElement('div');
      _toastContainer.id = 'fk-toast-container';
      _toastContainer.setAttribute('aria-live', 'polite');
      _toastContainer.style.cssText = 'position:fixed;bottom:24px;right:24px;z-index:999999;display:flex;flex-direction:column;gap:10px;pointer-events:none;max-width:380px;width:calc(100vw - 32px);';
      document.body.appendChild(_toastContainer);
    }
    const t = document.createElement('div');
    t.className = `fk-toast fk-toast-${type}`;
    const bg = type === 'error' ? '#FEF2F2' : type === 'success' ? '#F0FDF4' : type === 'warn' ? '#FFFBEB' : '#FFFFFF';
    const border = type === 'error' ? '#FCA5A5' : type === 'success' ? '#86EFAC' : type === 'warn' ? '#FDE68A' : '#E2E8F0';
    const color = type === 'error' ? '#991B1B' : type === 'success' ? '#166534' : type === 'warn' ? '#92400E' : '#0F172A';
    const icon = type === 'error' ? '⚠️' : type === 'success' ? '✓' : type === 'warn' ? 'ℹ️' : '💡';
    t.style.cssText = `background:${bg};border:1px solid ${border};color:${color};padding:12px 16px;border-radius:10px;box-shadow:0 10px 25px -5px rgba(0,0,0,0.12),0 8px 10px -6px rgba(0,0,0,0.06);font-size:13.5px;line-height:1.45;font-weight:500;display:flex;align-items:flex-start;gap:10px;pointer-events:auto;opacity:0;transform:translateY(12px);transition:all 0.22s cubic-bezier(0.16,1,0.3,1);font-family:Inter,system-ui,sans-serif;`;
    t.innerHTML = `<span style="font-size:15px;line-height:1;flex-shrink:0;">${icon}</span><span style="flex:1;">${escapeHtml(message)}</span>`;
    _toastContainer.appendChild(t);
    requestAnimationFrame(() => {
      t.style.opacity = '1';
      t.style.transform = 'translateY(0)';
    });
    setTimeout(() => {
      t.style.opacity = '0';
      t.style.transform = 'translateY(10px)';
      setTimeout(() => t.remove(), 250);
    }, duration);
  }

  FF.util = { escapeHtml, bytes, downloadBlob, objectURL, revokeAll, throwIfAborted, yieldToMain, baseName, extOf, el, loadScript, loadScripts, textToPdf, toast };
})();

/* FileKit ffmpeg engine — window.FF.media
   Lazy Web-Worker wrapper around the vendored single-threaded ffmpeg.wasm core
   (vendor/ffmpeg/). Exposes the same contract the video/audio tools expect:
     run({ inputs: [[name, File], ...], args, out, onProgress, signal }) → Uint8Array
     getFFmpeg(onProgress) → { writeFile, exec, listDir, readFile, deleteFile }
     terminate()
   The worker is created on first use; the core (~24 MB wasm) is fetched lazily. */
(() => {
  'use strict';
  const FF = (window.FF = window.FF || {});
  let worker = null;
  let readyPromise = null;
  let seq = 0;
  const pending = new Map();
  let initError = null;

  function call(type, payload) {
    return new Promise((resolve, reject) => {
      const id = ++seq;
      pending.set(id, { resolve, reject });
      worker.postMessage(Object.assign({ type, id }, payload));
    });
  }

  function ensureWorker() {
    if (readyPromise) return readyPromise;
    readyPromise = new Promise((resolve, reject) => {
      try {
        worker = new Worker('vendor/ffmpeg/ffmpeg-worker.js');
      } catch (err) {
        initError = new Error('Could not start the media engine: ' + err.message);
        reject(initError);
        return;
      }
      worker.onmessage = (e) => {
        const m = e.data;
        if (m.type === 'ready') { resolve(); return; }
        if (m.type === 'error') {
          initError = new Error('Media engine failed to load: ' + m.message);
          reject(initError);
          return;
        }
        const p = pending.get(m.id);
        if (!p) return;
        pending.delete(m.id);
        if (m.ok) {
          if (m.data !== undefined) {
            try { p.resolve(new Uint8Array(m.data)); }
            catch (e2) { p.resolve(m); }
          } else if (m.entries) {
            p.resolve(m.entries);
          } else {
            p.resolve(m);
          }
        } else {
          p.reject(new Error(m.error || 'media engine error'));
        }
      };
      worker.onerror = (e) => {
        const err = new Error('Media engine worker crashed: ' + (e && e.message || 'unknown'));
        initError = err;
        pending.forEach((p) => p.reject(err));
        pending.clear();
        readyPromise = null;
      };
      worker.postMessage({ type: 'init' });
    });
    return readyPromise;
  }

  const media = {
    get loaded() { return !!worker; },
    async run({ inputs, args, out, onProgress, signal }) {
      await ensureWorker();
      if (initError) throw initError;
      if (signal && signal.aborted) throw new DOMException('Aborted', 'AbortError');
      const inputData = [];
      for (const [name, file] of inputs) {
        inputData.push([name, await file.arrayBuffer()]);
      }
      const r = await call('run', { inputs: inputData, args: args || [], out });
      return r instanceof Uint8Array ? r : new Uint8Array(r && r.data !== undefined ? r.data : r);
    },
    async getFFmpeg(onProgress) {
      await ensureWorker();
      if (initError) throw initError;
      const f = {
        writeFile: async (name, data) => {
          const buf = data && data.buffer && !(data instanceof ArrayBuffer) ? data.buffer : data;
          await call('writeFile', { name, data: buf });
        },
        exec: async (args) => {
          const r = await call('exec', { args: args || [] });
          return r && r.code;
        },
        listDir: async (path) => {
          const r = await call('listDir', { path: path || '/' });
          return Array.isArray(r) ? r : (r && r.entries ? r.entries : []);
        },
        readFile: async (name) => {
          const r = await call('readFile', { name });
          if (r instanceof Uint8Array) return r;
          return new Uint8Array(r && r.data !== undefined ? r.data : r);
        },
        deleteFile: async (name) => { await call('deleteFile', { name }); },
        terminate: () => media.terminate(),
      };
      return f;
    },
    async terminate() {
      if (worker) {
        try { worker.terminate(); } catch (e) {}
        worker = null;
      }
      readyPromise = null;
      initError = null;
      pending.forEach((p) => p.reject(new Error('media engine terminated')));
      pending.clear();
    },
  };

  FF.media = media;

  // fetchFile helper the video-to-images tool expects
  window.FFmpegUtil = window.FFmpegUtil || {
    fetchFile: async (file) => new Uint8Array(await file.arrayBuffer()),
  };
})();

/* FileKit tool registry */
(() => {
  'use strict';
  const FF = (window.FF = window.FF || {});
  const _tools = new Map();

  function register(def) {
    if (!def || !def.id) throw new Error('Tool needs an id');
    if (_tools.has(def.id)) throw new Error(`Duplicate tool id: ${def.id}`);
    if (typeof def.run !== 'function') throw new Error(`Tool ${def.id} needs a run()`);
    _tools.set(def.id, Object.freeze({ multiple: false, live: false, fields: [], ...def }));
  }

  const get = (id) => _tools.get(id);
  const all = () => [..._tools.values()];
  const byCategory = () => {
    const m = new Map();
    for (const t of _tools.values()) {
      if (!m.has(t.category)) m.set(t.category, []);
      m.get(t.category).push(t);
    }
    return m;
  };

  FF.registry = { register, get, all, byCategory };
  FF.register = register;
})();

/* Declarative UX contracts */
