    'pdf-merge': ['#7b61e8', 'M10 8h8l5 5v13H10zM7 11h8l5 5v13H7z', 'M13 18h8M13 22h6'],
    'pdf-split': ['#7b61e8', 'M8 6h16v20H8zM16 6v20', 'M11 14h4M11 18h7'],
    'pdf-compress': ['#ef476f', 'M8 7h16v18H8z', 'M12 12l4 4 4-4M16 16V8'],
    'pdf-to-image': ['#f59e0b', 'M7 7h10l5 5v11H7zM17 7v6h5', 'M20 22H6v-8h14z'],
    'pdf-to-excel': ['#18ad68', 'M6 7h20v17H6zM6 13h20M6 19h20', 'M13 7v13'],
    'pdf-sign': ['#1e8ee8', 'M8 7h16v18H8z', 'M12 23c5-7 7-13 10-13 4 0-1 9 2 9'],
    'image-convert': ['#f3a400', 'M6 6h12l5 5v11H6z', 'M4 15l8-8 8 8'],
    'image-crop': ['#f3a400', 'M10 6v16a2 2 0 0 0 2 2h14', 'M6 10h14a2 2 0 0 1 2 2v14'],
    'image-resize': ['#f3a400', 'M7 7h18v18H7z', 'M7 16h18M16 7v18'],
