      /* ── Task-Specific Theme & Semantic Illustration Engine ── */
  window.FF.getToolTheme = function getToolTheme(toolId, category) {
    let id = (typeof toolId === 'string' ? toolId : (toolId?.id || window.FF?.activeToolId || window.location.hash.replace(/^#/, '') || '')).toLowerCase();
    let cat = (typeof category === 'string' ? category : (toolId?.category || '')).toLowerCase();

    // Task-specific Theme & Semantic Illustration Engine
    if (/compress|shrink/i.test(id) || id === 'pdf-compress' || id === 'compress-pdf' || id === 'pdf-to-pdf' || id === 'pdf-to-pdfa' || id === 'pdf-grayscale' || id === 'pdf-resize') {
      return { task: 'compress', color: '#EAB308', hover: '#CA8A04', bg: '#FEFCE8', border: '#FEF08A', glow: 'rgba(234,179,8,0.25)', cardBorder: '#FEF9C3' };
    }
    if (/edit-text|pdf-edit-text|^edit-pdf$|^edit$/i.test(id)) {
      return { task: 'edit', color: '#00A896', hover: '#008F80', bg: '#ECFDF5', border: '#99F6E4', glow: 'rgba(0,168,150,0.25)', cardBorder: '#CCFBF1' };
    }
    if (/merge/i.test(id)) {
      return { task: 'merge', color: '#4F46E5', hover: '#4338CA', bg: '#EEF2FF', border: '#C7D2FE', glow: 'rgba(79,70,229,0.25)', cardBorder: '#E0E7FF' };
    }
    if (/split|extract-range|extract-pages/i.test(id)) {
      return { task: 'split', color: '#E11D48', hover: '#BE123C', bg: '#FFF1F2', border: '#FECDD3', glow: 'rgba(225,29,72,0.25)', cardBorder: '#FFE4E6' };
    }
    if (/word|docx/i.test(id)) {
      return { task: 'pdf-to-word', color: '#2563EB', hover: '#1D4ED8', bg: '#EFF6FF', border: '#BFDBFE', glow: 'rgba(37,99,235,0.25)', cardBorder: '#DBEAFE' };
    }
    if (/excel|xlsx|csv/i.test(id)) {
      return { task: 'pdf-to-excel', color: '#059669', hover: '#047857', bg: '#ECFDF5', border: '#6EE7B7', glow: 'rgba(5,150,105,0.25)', cardBorder: '#A7F3D0' };
    }
    if (/repair/i.test(id)) {
      return { task: 'repair', color: '#059669', hover: '#047857', bg: '#ECFDF5', border: '#A7F3D0', glow: 'rgba(5,150,105,0.25)', cardBorder: '#A7F3D0' };
    }
    if (/ppt|powerpoint/i.test(id)) {
      return { task: 'ppt', color: '#EA580C', hover: '#C2410C', bg: '#FFF7ED', border: '#FED7AA', glow: 'rgba(234,88,12,0.25)', cardBorder: '#FED7AA' };
    }
    if (/image-to-pdf|jpg-to-pdf|png-to-pdf|pdf-to-image|pdf-to-jpg|extract-images/i.test(id)) {
      return { task: 'image-to-pdf', color: '#D97706', hover: '#B45309', bg: '#FFFBEB', border: '#FDE68A', glow: 'rgba(217,119,6,0.25)', cardBorder: '#FEF3C7' };
    }
    if (/ocr|extract-text/i.test(id)) {
      return { task: 'ocr', color: '#7C3AED', hover: '#6D28D9', bg: '#FAF5FF', border: '#DDD6FE', glow: 'rgba(124,58,237,0.25)', cardBorder: '#EDE9FE' };
    }
    if (/watermark/i.test(id)) {
      return { task: 'watermark', color: '#7C3AED', hover: '#6D28D9', bg: '#FAF5FF', border: '#DDD6FE', glow: 'rgba(124,58,237,0.25)', cardBorder: '#EDE9FE' };
    }
    if (/redact|pii|sanitize/i.test(id)) {
      return { task: 'redact', color: '#BE123C', hover: '#9F1239', bg: '#FFF1F2', border: '#FECDD3', glow: 'rgba(190,18,60,0.25)', cardBorder: '#FFE4E6' };
    }
    if (/crop/i.test(id)) {
      return { task: 'crop', color: '#0891B2', hover: '#0E7490', bg: '#ECFEFF', border: '#A5F3FC', glow: 'rgba(8,145,178,0.25)', cardBorder: '#CFFAFE' };
    }
    if (/page-numbers|number-pages/i.test(id)) {
      return { task: 'page-numbers', color: '#2563EB', hover: '#1D4ED8', bg: '#EFF6FF', border: '#BFDBFE', glow: 'rgba(37,99,235,0.25)', cardBorder: '#DBEAFE' };
    }
    if (/protect|lock/i.test(id) && !/unlock/i.test(id)) {
      return { task: 'protect', color: '#0F766E', hover: '#115E59', bg: '#F0FDFA', border: '#99F6E4', glow: 'rgba(15,118,110,0.25)', cardBorder: '#CCFBF1' };
    }
    if (/unlock/i.test(id)) {
      return { task: 'unlock', color: '#E11D48', hover: '#BE123C', bg: '#FFF1F2', border: '#FECDD3', glow: 'rgba(225,29,72,0.25)', cardBorder: '#FFE4E6' };
    }
    if (/sign/i.test(id)) {
      return { task: 'sign', color: '#0F766E', hover: '#115E59', bg: '#F0FDFA', border: '#99F6E4', glow: 'rgba(15,118,110,0.25)', cardBorder: '#CCFBF1' };
    }
    if (/form/i.test(id)) {
      return { task: 'sign', color: '#0F766E', hover: '#115E59', bg: '#F0FDFA', border: '#99F6E4', glow: 'rgba(15,118,110,0.25)', cardBorder: '#CCFBF1' };
    }
    if (/flatten/i.test(id)) {
      return { task: 'flatten', color: '#4F46E5', hover: '#4338CA', bg: '#EEF2FF', border: '#C7D2FE', glow: 'rgba(79,70,229,0.25)', cardBorder: '#E0E7FF' };
    }
    if (/organize|rotate/i.test(id)) {
      return { task: 'organize', color: '#4F46E5', hover: '#4338CA', bg: '#EEF2FF', border: '#C7D2FE', glow: 'rgba(79,70,229,0.25)', cardBorder: '#E0E7FF' };
    }
    if (/audio/i.test(id) || cat === 'audio') {
      return { task: 'audio', color: '#E11D48', hover: '#BE123C', bg: '#FFF1F2', border: '#FECDD3', glow: 'rgba(225,29,72,0.25)', cardBorder: '#FFE4E6' };
    }
    if (cat === 'images') {
      return { task: 'images', color: '#EA580C', hover: '#C2410C', bg: '#FFF7ED', border: '#FDBA74', glow: 'rgba(234,88,12,0.25)', cardBorder: '#FED7AA' };
    }
    if (cat === 'documents') {
      return { task: 'documents', color: '#2563EB', hover: '#1D4ED8', bg: '#EFF6FF', border: '#BFDBFE', glow: 'rgba(37,99,235,0.25)', cardBorder: '#DBEAFE' };
    }
    return { task: 'pdf', color: '#E5252A', hover: '#DC2626', bg: '#FEF2F2', border: '#FCA5A5', glow: 'rgba(229,37,42,0.25)', cardBorder: '#FECACA' };
  };

