    function toggleFavorite(id, e) {
      if (e) e.stopPropagation();
      if (favoriteIds.includes(id)) {
        favoriteIds = favoriteIds.filter(x => x !== id);
      } else {
        favoriteIds.push(id);
      }
      persistLists();
      updatePersonalCounts();
      renderAppWorkspace();
    }

    function appCard(tool) {
      const isFav = favoriteIds.includes(tool.id);
      const catSlug = tool.category.toLowerCase().replace(/[^a-z0-9]/g, '');
      const favBtn = el('button', {
        class: `card-star-btn${isFav ? ' active' : ''}`,
        type: 'button',
        title: isFav ? 'Remove from favorites' : 'Add to favorites',
        'aria-label': `${isFav ? 'Starred' : 'Unstarred'} ${tool.name}`
      }, [el('span', { text: '★' })]);

      favBtn.addEventListener('click', (e) => toggleFavorite(tool.id, e));

      const isPdf = tool.category === 'PDF';
      const cardEl = el('article', {
        class: `app-tool-card cat-${catSlug}${isPdf ? ' cat-pdf-card' : ''}${appViewMode === 'list' ? ' list-card' : ''}`,
        tabindex: '0',
        role: 'button'
      }, [
        el('div', { class: 'card-header-row' }, [
          iconFor(tool, 'card-main-icon'),
          el('div', { class: 'card-meta-wrap' }, [
            el('span', { class: `category-tag tag-${catSlug}`, text: tool.category }),
            favBtn
          ])
        ]),
        el('div', { class: 'card-body-content' }, [
          el('h4', { class: 'card-tool-name', text: tool.name }),
          el('p', { class: 'card-tool-desc', text: tool.description || `${tool.category} browser tool` })
        ]),
        el('div', { class: 'card-footer-row' }, [
          el('span', { class: 'local-pill', text: '⚡ 100% Local' }),
          el('span', { class: 'launch-btn-label', text: 'Open Tool →' })
        ])
      ]);

      cardEl.addEventListener('click', () => openTool(tool.id));
      cardEl.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openTool(tool.id);
        }
      });

      return cardEl;
    }

    function showHome(scrollTarget = null) {
      FF.util.revokeAll();
      home.hidden = false; toolView.hidden = true; if (appView) appView.hidden = true; document.title = 'FileKit — Every File Tool You Need';
      const topbar = document.querySelector('.topbar'); if (topbar) topbar.hidden = false;
      const appTopbar = document.getElementById('app-topbar'); if (appTopbar) appTopbar.hidden = true;
      const footer = document.querySelector('footer'); if (footer) footer.hidden = false;
      window.history.replaceState({}, '', location.pathname);
      requestAnimationFrame(() => {
        if (scrollTarget) document.getElementById(scrollTarget)?.scrollIntoView({ behavior: 'smooth' });
        else { window.scrollTo({ top: 0, behavior: 'smooth' }); const heading = home.querySelector('h1'); if (heading) { heading.tabIndex = -1; heading.focus({ preventScroll: true }); } }
      });
    }

    function showApp(category = 'Home') {
      FF.util.revokeAll();
      home.hidden = true; toolView.hidden = true; if (appView) appView.hidden = false;
      const topbar = document.querySelector('.topbar'); if (topbar) topbar.hidden = false;
      const appTopbar = document.getElementById('app-topbar'); if (appTopbar) appTopbar.hidden = true;
      const footer = document.querySelector('footer'); if (footer) footer.hidden = true;
      appCategory = category || 'Home';
      appSpecialFilter = '';
      window.history.replaceState({ app: true, category: appCategory }, '', '#app');
      window.scrollTo({ top: 0, behavior: 'instant' });
      renderAppWorkspace();
    }

    // --- Hamburger Category Drawer Controller ---
    const appHamburgerBtn = document.getElementById('app-hamburger-btn');
    const appHamburgerClose = document.getElementById('app-hamburger-close');
