    const appDrawerBackdrop = document.getElementById('app-drawer-backdrop');
    const appDrawerNav = document.getElementById('app-drawer-nav');

    function openAppDrawer() {
      if (appHamburgerDrawer) appHamburgerDrawer.hidden = false;
      if (appDrawerBackdrop) appDrawerBackdrop.hidden = false;
      document.body.classList.add('app-drawer-open');
      renderAppDrawerNav();
    }

    function closeAppDrawer() {
      if (appHamburgerDrawer) appHamburgerDrawer.hidden = true;
      if (appDrawerBackdrop) appDrawerBackdrop.hidden = true;
      document.body.classList.remove('app-drawer-open');
    }

    if (appHamburgerBtn) appHamburgerBtn.addEventListener('click', openAppDrawer);
    if (appHamburgerClose) appHamburgerClose.addEventListener('click', closeAppDrawer);
    if (appDrawerBackdrop) appDrawerBackdrop.addEventListener('click', closeAppDrawer);

    function renderAppDrawerNav() {
      if (!appDrawerNav) return;
      appDrawerNav.textContent = '';

      const allBtn = el('button', {
        class: `drawer-item${appCategory === 'All' && !appSpecialFilter ? ' active' : ''}`,
        type: 'button'
      }, [
        el('span', { class: 'sidebar-dot all-dot' }),
        el('span', { class: 'drawer-item-label', text: 'All Tools' }),
        el('b', { class: 'drawer-item-count', text: tools.length })
      ]);
      allBtn.addEventListener('click', () => { appCategory = 'All'; appSpecialFilter = ''; closeAppDrawer(); renderAppWorkspace(); });
      appDrawerNav.append(allBtn);

      categories.forEach(cat => {
        const count = (byCategory.get(cat) || []).length;
        const slug = cat.toLowerCase().replace(/[^a-z0-9]/g, '');
        const btn = el('button', {
          class: `drawer-item cat-${slug}${appCategory === cat && !appSpecialFilter ? ' active' : ''}`,
          type: 'button'
        }, [
          el('span', { class: `sidebar-dot dot-${slug}` }),
          el('span', { class: 'drawer-item-label', text: cat }),
          el('b', { class: 'drawer-item-count', text: count })
        ]);
        btn.addEventListener('click', () => { appCategory = cat; appSpecialFilter = ''; closeAppDrawer(); renderAppWorkspace(); });
        appDrawerNav.append(btn);
      });

      const drawerFavBtn = document.getElementById('drawer-favorite-btn');
      if (drawerFavBtn) {
        drawerFavBtn.onclick = () => { appSpecialFilter = 'favorites'; closeAppDrawer(); renderAppWorkspace(); };
      }
      const drawerRecBtn = document.getElementById('drawer-recent-btn');
      if (drawerRecBtn) {
        drawerRecBtn.onclick = () => { appSpecialFilter = 'recents'; closeAppDrawer(); renderAppWorkspace(); };
      }
      const favBadge = document.getElementById('drawer-favorite-count');
      if (favBadge) favBadge.textContent = favoriteIds.length;
      const recBadge = document.getElementById('drawer-recent-count');
      if (recBadge) recBadge.textContent = recentIds.length;
    }

    // --- Smart Drag & Drop File Zone Controller ---
    const dropzoneSection = document.getElementById('app-dropzone-section');
    const fileInput = document.getElementById('app-file-input');
    const chooseFileBtn = document.getElementById('app-choose-file-btn');
    const dropzoneIdle = document.getElementById('dropzone-idle');
    const dropzoneDetected = document.getElementById('dropzone-detected');
    const clearDroppedFileBtn = document.getElementById('clear-dropped-file');

    function formatBytes(bytes) {
      if (bytes === 0) return '0 Bytes';
      const k = 1024;
      const sizes = ['Bytes', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    }

    function detectCategoryFromFile(file) {
      const name = file.name.toLowerCase();
      const ext = name.split('.').pop() || '';
      const type = file.type.toLowerCase();

      if (ext === 'pdf' || type.includes('pdf')) return 'PDF';
      if (['jpg', 'jpeg', 'png', 'webp', 'gif', 'svg', 'bmp', 'ico', 'avif'].includes(ext) || type.startsWith('image/')) return 'Images';
      if (['pptx', 'ppt'].includes(ext) || type.includes('presentation') || type.includes('powerpoint')) return 'Presentation';
      if (['docx', 'doc', 'txt', 'md', 'rtf', 'odt'].includes(ext) || type.includes('word') || type.includes('text')) return 'Documents';
      if (['xlsx', 'xls', 'csv', 'tsv', 'ods'].includes(ext) || type.includes('sheet') || type.includes('excel') || type.includes('csv')) return 'Spreadsheets';
      if (['mp4', 'webm', 'mov', 'mkv', 'avi', 'wmv'].includes(ext) || type.startsWith('video/')) return 'Video';
      if (['mp3', 'wav', 'ogg', 'flac', 'm4a', 'aac'].includes(ext) || type.startsWith('audio/')) return 'Audio';
      if (['zip', 'tar', 'gz', 'rar', '7z', 'bz2'].includes(ext) || type.includes('zip') || type.includes('tar') || type.includes('compressed')) return 'Archive';
      if (['json', 'xml', 'yaml', 'js', 'html', 'css', 'sql'].includes(ext) || type.includes('json') || type.includes('xml')) return 'Developer';
      return 'Documents';
    }

