    function closeRailMoreMenu() {
      document.querySelectorAll('.rail-more-menu').forEach(m => m.remove());
      document.querySelectorAll('.rail-item.is-more-open').forEach(b => b.classList.remove('is-more-open'));
      if (window._railMoreOutside) {
        document.removeEventListener('pointerdown', window._railMoreOutside, true);
        window._railMoreOutside = null;
      }
      if (window._railMoreKey) {
        document.removeEventListener('keydown', window._railMoreKey, true);
        window._railMoreKey = null;
      }
    }

    function openRailMoreMenu(anchorBtn, items) {
      closeRailMoreMenu();
      if (!items || !items.length) return;

      menu.innerHTML = items.map(it => `
        <button type="button" class="rail-more-item" role="menuitem" data-tool-id="${it.toolId}">
          <span class="rail-more-ico" style="--c:${it.color || '#38bdf8'}">${it.svg || ''}</span>
          <span class="rail-more-label">${it.title}</span>
        </button>`).join('');

      document.body.appendChild(menu);
      anchorBtn.classList.add('is-more-open');

      const place = () => {
        const r = anchorBtn.getBoundingClientRect();
        const mw = menu.offsetWidth || 200;
        const mh = menu.offsetHeight || 240;
        let left = r.right + 10;
        let top = r.top + r.height / 2 - mh / 2;
        if (left + mw > window.innerWidth - 8) left = Math.max(8, r.left - mw - 10);
        if (top < 8) top = 8;
        if (top + mh > window.innerHeight - 8) top = Math.max(8, window.innerHeight - mh - 8);
        menu.style.left = left + 'px';
        menu.style.top = top + 'px';
      };
      place();
      requestAnimationFrame(place);

      menu.querySelectorAll('.rail-more-item').forEach(itemBtn => {
        itemBtn.addEventListener('click', () => {
          const id = itemBtn.dataset.toolId;
          closeRailMoreMenu();
          document.querySelectorAll('.app-sidebar-rail .rail-item').forEach(r => r.classList.remove('active'));
          anchorBtn.classList.add('active');
          if (id) openTool(id);
        });
      });

      window._railMoreOutside = (e) => {
        if (menu.contains(e.target) || anchorBtn.contains(e.target)) return;
        closeRailMoreMenu();
      };
      window._railMoreKey = (e) => {
        if (e.key === 'Escape') closeRailMoreMenu();
      };
      document.addEventListener('pointerdown', window._railMoreOutside, true);
      document.addEventListener('keydown', window._railMoreKey, true);
      window.addEventListener('resize', closeRailMoreMenu, { once: true });
    }

    function updateSidebarForFileCategory(category, file) {
      const railNav = document.querySelector('.app-sidebar-rail .rail-nav');
      if (!railNav) return;

      if (!window._defaultRailMarkup) {
        window._defaultRailMarkup = railNav.innerHTML;
      }

      closeRailMoreMenu();
      closeAllToolsFlyout();

      let railTools = FORMAT_RAIL_TOOLS[category];
      if (!railTools) {
        let catTools = tools.filter(t => t.category === category);
        if (!catTools.length) catTools = tools.filter(t => t.category === 'PDF');
        railTools = catTools.slice(0, 8).map(t => ({
          title: t.name.replace(/PDF|Image|Document|Video|Audio/gi, '').trim() || t.name,
          toolId: t.id,
          svg: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>'
        }));
      }

      railNav.innerHTML = '';
      railTools.forEach((tool, idx) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `rail-item ${idx === 0 ? 'active' : ''}${tool.isMore ? ' rail-item-more' : ''}`;
        btn.title = tool.fullTitle || tool.title;
        if (tool.isMore) btn.setAttribute('aria-haspopup', 'menu');

        btn.innerHTML = `<span class="rail-icon">${tool.svg}</span><span class="rail-label">${tool.title}</span>`;

        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          if (tool.isMore) {
            if (btn.classList.contains('is-more-open')) {
              closeRailMoreMenu();
              return;
            }
            document.querySelectorAll('.app-sidebar-rail .rail-item').forEach(r => r.classList.remove('active'));
            btn.classList.add('active');
            openRailMoreMenu(btn, tool.more || []);
            return;
          }
          closeRailMoreMenu();
          document.querySelectorAll('.app-sidebar-rail .rail-item').forEach(r => r.classList.remove('active'));
          btn.classList.add('active');
          openTool(tool.toolId);
        });

        railNav.appendChild(btn);
      });
    }

    function restoreDefaultSidebar() {
      closeRailMoreMenu();
      closeAllToolsFlyout();
      const railNav = document.querySelector('.app-sidebar-rail .rail-nav');
      if (railNav && window._defaultRailMarkup) {
        railNav.innerHTML = window._defaultRailMarkup;
        document.querySelectorAll('.rail-item[data-rail-cat], .app-nav-links button[data-rail-cat]').forEach(btn => {
          btn.addEventListener('click', () => {
            appCategory = btn.dataset.railCat;
            appTask = '';
            appSpecialFilter = '';
            if (appWorkspaceSearch) appWorkspaceSearch.value = '';
            renderAppWorkspace();
          });
        });
        bindRailTaskButtons();
        renderPinnedRailItems();
        bindAllToolsFlyout();
      }
    }

    function handleDroppedFile(file) {
      if (!file) return;
      const category = detectCategoryFromFile(file);
      const ext = file.name.split('.').pop()?.toUpperCase() || 'FILE';

      if (dropzoneIdle) dropzoneIdle.hidden = true;
      if (dropzoneDetected) dropzoneDetected.hidden = false;

      const fileNameEl = document.getElementById('detected-file-name');
      if (fileNameEl) fileNameEl.textContent = file.name;
      const fileMetaEl = document.getElementById('detected-file-meta');
      if (fileMetaEl) fileMetaEl.textContent = `${formatBytes(file.size)} · ${ext} File`;
      const formatLabelEl = document.getElementById('detected-format-label');
      if (formatLabelEl) formatLabelEl.textContent = ext;
      const iconEl = document.getElementById('detected-file-icon');
      if (iconEl) {
        const meta = CATEGORY_META[category] || { icon: '📄' };
        iconEl.textContent = meta.icon;
      }

      // Dynamically transform sidebar rail icons for this specific format
      updateSidebarForFileCategory(category, file);
    }

    // Expose app-side helpers so workspace mounts (e.g. the Media hub) can
    // drive the rail exactly like the app-level dropzone does.
    window.FF.app = window.FF.app || {};
    window.FF.app.openTool = openTool;
    window.FF.app.updateSidebarForFileCategory = updateSidebarForFileCategory;
    window.FF.app.restoreDefaultSidebar = restoreDefaultSidebar;
    window.FF.app.detectCategoryFromFile = detectCategoryFromFile;
    window.FF.app.formatRailTools = (cat) => FORMAT_RAIL_TOOLS[cat] || [];

    if (chooseFileBtn && fileInput) {
      chooseFileBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        fileInput.click();
      });
    }

    if (fileInput) {
      fileInput.addEventListener('change', (e) => {
        if (e.target.files && e.target.files[0]) {
          handleDroppedFile(e.target.files[0]);
        }
      });
    }

    if (dropzoneSection) {
      dropzoneSection.addEventListener('click', (e) => {
        if (!e.target.closest('.smart-matched-tools') && !e.target.closest('#clear-dropped-file') && !e.target.closest('#app-choose-file-btn')) {
          fileInput?.click();
        }
      });
      ['dragenter', 'dragover'].forEach(evtName => {
        dropzoneSection.addEventListener(evtName, (e) => {
          e.preventDefault();
          e.stopPropagation();
          dropzoneSection.classList.add('drag-active');
        });
      });
      ['dragleave', 'drop'].forEach(evtName => {
        dropzoneSection.addEventListener(evtName, (e) => {
          e.preventDefault();
          e.stopPropagation();
          dropzoneSection.classList.remove('drag-active');
        });
      });
      dropzoneSection.addEventListener('drop', (e) => {
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]) {
          handleDroppedFile(e.dataTransfer.files[0]);
        }
      });
    }

    if (clearDroppedFileBtn) {
      clearDroppedFileBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (dropzoneIdle) dropzoneIdle.hidden = false;
        if (dropzoneDetected) dropzoneDetected.hidden = true;
        if (fileInput) fileInput.value = '';
        restoreDefaultSidebar();
      });
    }

