    function renderAppWorkspace() {
      if (!appView) return;
      window.scrollTo({ top: 0, behavior: 'instant' });
      const q = (appWorkspaceSearch?.value || '').trim().toLowerCase();
      const appHomeView = document.getElementById('app-home-view');
      const appCategoryView = document.getElementById('app-category-view');
      const appWorkspaceToolView = document.getElementById('app-workspace-tool-view');

      // The rail keeps its default task icons until a file is actually dropped —
      // handleDroppedFile() then swaps it to the tools for that file's format.
      if (appCategory === 'Home' || appCategory === 'More') {
        restoreDefaultSidebar();
      }

      // Sync Rail Items active state
      document.querySelectorAll('.rail-item').forEach(item => {
        const itemCat = item.dataset.railCat;
        const isHomeDefault = (!appTask && (!appCategory || appCategory === 'Home' || appCategory === 'All')) && item.dataset.taskRail === 'compress';
        const selected = isHomeDefault || (itemCat === appCategory && !appSpecialFilter && appCategory !== 'Home');
        item.classList.toggle('active', selected);
        if (selected) item.setAttribute('aria-current','page'); else item.removeAttribute('aria-current');
      });

      const workspaceTitle = document.getElementById('app-workspace-title');

      if ((!appCategory || appCategory === 'Home' || appCategory === 'All') && !q) {
        // --- SHOW SMALLPDF APP HOME VIEW ---
        if (workspaceTitle) workspaceTitle.textContent = 'Home';
        if (appHomeView) appHomeView.hidden = false;
        if (appCategoryView) appCategoryView.hidden = true;
        if (appWorkspaceToolView) appWorkspaceToolView.hidden = true;
        renderSmallpdfHome();
      } else {
        // --- SHOW CATEGORY DROPZONE VIEW ---
        if (appHomeView) appHomeView.hidden = true;
        if (appCategoryView) appCategoryView.hidden = false;
        if (appWorkspaceToolView) appWorkspaceToolView.hidden = true;

        const config = RAIL_CONFIG[appCategory] || RAIL_CONFIG['Convert'];
        if (workspaceTitle) workspaceTitle.textContent = config.title || 'PDF Tools';

        const TASK_DATA = {
          compress: {
            sub: 'Add any <strong>PDF</strong>, <strong>Image</strong>, <strong>Video</strong>, <strong>Audio</strong>, or <strong>ZIP</strong> file to compress',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'IMG', cls: 'fmt-png' }, { name: 'VIDEO', cls: 'fmt-ppt' }, { name: 'AUDIO', cls: 'fmt-xls' }, { name: 'ZIP', cls: 'fmt-doc' }]
          },
          convert: {
            sub: 'Add any <strong>PDF</strong>, <strong>Image</strong>, <strong>Video</strong>, <strong>Audio</strong>, <strong>Word</strong>, <strong>Excel</strong>, or <strong>eBook</strong> to convert',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'DOC', cls: 'fmt-doc' }, { name: 'XLS', cls: 'fmt-xls' }, { name: 'IMG', cls: 'fmt-png' }, { name: 'MEDIA', cls: 'fmt-ppt' }]
          },
          organize: {
            sub: 'Add <strong>PDFs</strong>, <strong>Images</strong>, or <strong>Archives</strong> to merge, split, or rearrange',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'IMG', cls: 'fmt-png' }, { name: 'ZIP', cls: 'fmt-doc' }]
          },
          edit: {
            sub: 'Add <strong>PDF</strong>, <strong>Image</strong>, <strong>Video</strong>, or <strong>Audio</strong> files to edit, trim, crop, or annotate',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'IMG', cls: 'fmt-png' }, { name: 'VIDEO', cls: 'fmt-ppt' }, { name: 'AUDIO', cls: 'fmt-xls' }]
          },
          scan: {
            sub: 'Add <strong>PDF</strong>, <strong>JPG</strong>, or <strong>PNG</strong> documents to scan & extract text',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'JPG', cls: 'fmt-jpg' }, { name: 'PNG', cls: 'fmt-png' }]
          },
          qr: {
            sub: 'Add <strong>PNG</strong>, <strong>JPG</strong>, <strong>WEBP</strong>, or <strong>SVG</strong> files with QR codes or barcodes',
            formats: [{ name: 'PNG', cls: 'fmt-png' }, { name: 'JPG', cls: 'fmt-jpg' }, { name: 'WEBP', cls: 'fmt-doc' }, { name: 'SVG', cls: 'fmt-xls' }]
          },
          workflow: {
            sub: 'Add <strong>PDF</strong>, <strong>Image</strong>, or <strong>Document</strong> files to run automated workflows',
            formats: [{ name: 'PDF', cls: 'fmt-pdf' }, { name: 'IMG', cls: 'fmt-png' }, { name: 'DOC', cls: 'fmt-doc' }]
          }
        };

        const activeTaskInfo = (appTask && appTask !== 'more' && TASK_DATA[appTask]) ? TASK_DATA[appTask] : null;
        const subTextEl = document.getElementById('drop-sub-text');
        if (subTextEl) subTextEl.innerHTML = activeTaskInfo ? activeTaskInfo.sub : (config.sub || '');

        const fmtRow = document.getElementById('supported-formats-row');
        const activeFormats = activeTaskInfo ? activeTaskInfo.formats : (config.formats || []);
        if (fmtRow && activeFormats.length) {
          fmtRow.innerHTML = '<span class="fmt-label">Supported formats:</span>' +
            activeFormats.map(f => `<span class="fmt-badge ${f.cls}">${f.name}</span>`).join('');
        }

        const appCategoryHub = document.getElementById('app-category-hub');
        const toolsSection = document.getElementById('app-workspace-tools-section');

        if (appCategoryHub) appCategoryHub.hidden = true;
        if (appToolsGrid) appToolsGrid.hidden = false;
        if (toolsSection) toolsSection.hidden = false;

        let filtered;
        if (q) {
          filtered = tools.filter(t => `${t.name} ${t.description || ''} ${t.category}`.toLowerCase().includes(q));
        } else if (appTask && taskToolIds[appTask]?.length) {
          filtered = tools.filter(t => taskToolIds[appTask].includes(t.id));
        } else if (appTask === 'more') {
          filtered = tools.filter(t => t.category === 'PDF');
        } else if (config.filter) {
          filtered = tools.filter(config.filter);
        } else {
          filtered = tools.filter(t => t.category === appCategory || appCategory === 'PDF' && t.category === 'PDF');
        }

        if (!filtered.length) {
          filtered = tools.filter(t => t.category === 'PDF');
        }

        if (appToolsGrid) {
          appToolsGrid.textContent = '';
          filtered.forEach(t => appToolsGrid.append(appCard(t)));
        }
      }
    }


    // View Mode & Personal Filter listeners
    document.getElementById('view-mode-grid')?.addEventListener('click', () => {
      appViewMode = 'grid';
      document.getElementById('view-mode-grid').classList.add('active');
      document.getElementById('view-mode-list').classList.remove('active');
      renderAppWorkspace();
    });
    document.getElementById('view-mode-list')?.addEventListener('click', () => {
      appViewMode = 'list';
      document.getElementById('view-mode-list').classList.add('active');
      document.getElementById('view-mode-grid').classList.remove('active');
      renderAppWorkspace();
    });
    document.getElementById('app-favorite-filter')?.addEventListener('click', () => {
      appSpecialFilter = appSpecialFilter === 'favorites' ? '' : 'favorites';
      renderAppWorkspace();
    });
    document.getElementById('app-recent-filter')?.addEventListener('click', () => {
      appSpecialFilter = appSpecialFilter === 'recents' ? '' : 'recents';
      renderAppWorkspace();
    });
    document.querySelectorAll('[data-launch-tool]').forEach(btn => {
      btn.addEventListener('click', () => {
        window._navFromAppWorkspace = true;
        const toolId = btn.dataset.launchTool;
        openTool(toolId);
        window._navFromAppWorkspace = false;
      });
    });

    if (appWorkspaceSearch) {
      appWorkspaceSearch.addEventListener('input', renderAppWorkspace);
    }
    document.getElementById('app-clear-search')?.addEventListener('click', () => {
      if (appWorkspaceSearch) appWorkspaceSearch.value = '';
      appCategory = 'All';
      appSpecialFilter = '';
      renderAppWorkspace();
    });

    
