          'pdf-unlock': { id: 'pdf-unlock', name: 'Unlock', category: 'PDF', description: 'Remove PDF password' },
          'pdf-page-numbers': { id: 'pdf-page-numbers', name: 'Number Pages', category: 'PDF' },
          'pdf-rotate': { id: 'pdf-rotate', name: 'Rotate', category: 'PDF' },
          'pdf-watermark': { id: 'pdf-watermark', name: 'Watermark', category: 'PDF' },
